  setup(props, { slots, attrs }) {
    return () =>
      h(
        Graph,
        mergeProps(
          {
            title: props.title ?? props.type,
            corner: props.corner,
            className: props.className,
            role: 'note',
          },
          attrs,
        ),
        () =>
          // Resolve the upstream padding override locally; shared frame stays unchanged.
          h('div', { class: 'min-w-0 px-5 sm:px-8 py-6 sm:py-6' }, [
