                        line.kind === 'command' ? props.prompt : ' ',
                      ),
                      h('span', line.text || ' '),
                    ],
                  ),
                  [[vReveal, { delay: Math.min(index, 5) * 40 }]],
                ),
              ),
            ),
          ),
      )
    }
  },
})

